def choose_cable(mbps, metres):
    table = [('Cat 5', 100, 100), ('Cat 5E', 1000, 100), ('Cat 6', 1000, 100), ('Cat 6', 10000, 55)]
    for name, speed, length in table:
        if mbps <= speed and metres <= length:
            return name
    return 'None'
